SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name,si.id AS instance_id,si.suffix,si.storage_object_id,so.physical_key,so.etag,so.size,se.path,se.companion_of FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_objects so ON so.id=si.storage_object_id LEFT JOIN albums a ON a.id=sm.album_id LEFT JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE (a.name LIKE '页间曲%') OR sm.id IN ('sm-upload-0112a6d9-283','sm-upload-2c6e632f-4ae','sm-upload-6a381b8f-020','sm-upload-8ca7055e-888','sm-upload-a4de5316-99a','sm-upload-bba1a72e-f0c','sm-upload-cc1e80b9-244','sm-upload-d11b6d58-141','sm-upload-d642ecae-43c','sm-upload-fa2c02f7-a2d') ORDER BY sm.album_id,sm.track,sm.id